#include <bits/stdc++.h>
using namespace std;

long long f1( vector<long long>& vecc1, int num1, int num2, int num3){
    
    long long yxz, num4, num5, num6;
    
    int num12, num13;
    
    num12 = 2*num2;
    num12 = num12 -num1;
    
    num13= num3-num2;
    
    num13 =num13- num1;
    num4 = vecc1[num1];
    
    num4 = 2* num4;


    num5 = vecc1[num12];
    
    num6 = vecc1[num13];
    num6 = 3*num6;
    
    yxz = num4 + num5;
    yxz = yxz +num6;
    
    return yxz;
}

long long f2( vector<long long> & vecc2, int n1){
    vector<long long> vecc1;
    
    long long num7, num8, num14, num15;
    
    int num3, num9, num10, num11;
    num3= 3*n1;
    
    vecc1.assign(num3+1, 0 );
    
    sort(vecc2.rbegin(), vecc2.rend());
    
    for(int i=0;i<num3; i++){
        vecc1[i+1]  = vecc1[i];
        
        vecc1[i+1] = vecc1[i+1] + vecc2[i];
    }
    
    num7=0;
    for(int i=0; i<=n1; i++){
        num9 =0;
        num10 =i;
        
        while(num9< num10){
            num11 = num9 +num10;
            num11 = num11/2;
            
            num14= f1(vecc1, num11+1, i, num3);
            
            num15 = f1(vecc1, num11, i, num3);
            
            if(num14> num15){
                num9 = num11 +1;
            }
            else{
                
                num10=num11;
            }
        }
        num8 = f1(vecc1, num9, i, num3);
        num7 = max(num7, num8);
    }
    
    return num7;
    
    
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    
    int t, n1, num3;
    
    vector<long long> vecc2;
    
    cin>>t;
    while(t--){
        
        cin>>n1;
        num3 = 3*n1;
        
        vecc2.assign(num3, 0);
        for(int i=0; i< num3; i++){
            cin >> vecc2[i];
        }
        
        cout<< f2(vecc2,n1) << endl;
    }
    return 0;
}
